current_chapter_title = ""
current_chapter_lines = []
in_notes_section = False

def is_notes_line(line):
    """Check if a line is a word-count note or author's note (to be excluded)."""
    stripped = line.strip()
    # Skip word count notes in parentheses or brackets
    if stripped.startswith('(Word count for Chapter'):
        return True
    if stripped.startswith('(Conclusion of Chapters'):
        return True
    if stripped.startswith('(Self-Correction:'):
        return True
    if stripped.startswith('[Expanding'):
        return True
    if stripped.startswith('[The actual chapter continues'):
        return True
    if stripped.startswith('[End of Chapter'):
        return True
    return False

def is_chapter_header(line):
    """Check if a line is a chapter header."""
    stripped = line.strip()
    # Match: ## Chapter N -- Title or # Chapter N: Title
    match = re.match(r'^#{1,2}\s+Chapter\s+(\d+)\s*[-:–—]\s*(.*)', stripped)
    if match:
        return int(match.group(1)), match.group(2).strip()
    # Also match: ## Chapter N -- Title (with just the number)
    match = re.match(r'^#{1,2}\s+Chapter\s+(\d+)', stripped)
    if match:
        # The rest could be after a dash
        rest = stripped[match.end():]
        rest = rest.lstrip('-–— ')
        return int(match.group(1)), rest.strip()
    return None

